class PaymentScreen extends StatefulWidget { const PaymentScreen({super.key}); @override State<PaymentScreen> createState() => _PaymentScreenState(); }
class _PaymentScreenState extends State<PaymentScreen> {
  final phone = TextEditingController();
  final operators = const {'yemen_mobile':'يمن موبايل','y':'واي','you':'يو YOU','sabafon':'سبأفون','yemen4g':'يمن 4G','yemen_net':'يمن نت','aden_net':'عدن نت'};
  String selected = 'yemen_mobile';
  @override void initState(){super.initState();final app=context.read<AppController>();if(app.user?.phone!=null)phone.text=app.user!.phone;if(app.catalogServices.isEmpty)app.refreshCatalog();}
  @override void dispose(){phone.dispose();super.dispose();}
  @override Widget build(BuildContext context){final app=context.watch<AppController>();final services=app.servicesFor(selected);final color=serviceColor('$selected ${operators[selected]}');return Scaffold(backgroundColor:AppColors.page,appBar:AppBar(title:Text(operators[selected]!,style:const TextStyle(fontSize:15,fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:app.refreshCatalog,icon:const Icon(Icons.sync_rounded))]),body:RefreshIndicator(color:color,onRefresh:app.refreshCatalog,child:ListView(padding:const EdgeInsets.all(12),children:[
    SizedBox(height:42,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:operators.length,separatorBuilder:(_,__)=>const SizedBox(width:6),itemBuilder:(_,i){final e=operators.entries.elementAt(i);final active=e.key==selected;return ChoiceChip(selected:active,label:Text(e.value,style:const TextStyle(fontSize:9,fontWeight:FontWeight.w900)),selectedColor:color,backgroundColor:Colors.white,side:BorderSide(color:active?color:AppColors.border),labelStyle:TextStyle(color:active?Colors.white:Colors.black87),onSelected:(_)=>setState(()=>selected=e.key));})),
    const SizedBox(height:9), PageCard(child:Row(children:[const Icon(Icons.phone_android_rounded,color:AppColors.burgundy),const SizedBox(width:7),Expanded(child:TextField(controller:phone,textDirection:TextDirection.ltr,keyboardType:TextInputType.phone,inputFormatters:[FilteringTextInputFormatter.digitsOnly],maxLength:9,decoration:const InputDecoration(labelText:'رقم الهاتف (9 أرقام)',counterText:'',isDense:true,border:InputBorder.none,filled:false)))])),
    const SizedBox(height:10),
    Container(padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:color.withOpacity(.08),borderRadius:BorderRadius.circular(15)),child:Row(children:[Icon(Icons.auto_awesome_rounded,color:color,size:18),const SizedBox(width:7),Expanded(child:Text('الخدمات أدناه تأتي من كتالوج الخادم، بما في ذلك الحقول والفئات والعناصر والأسعار.',style:TextStyle(fontSize:9.5,color:color,fontWeight:FontWeight.w800))) ])),
    const SizedBox(height:10),
    if(services.isEmpty) const EmptyState(text:'لا توجد خدمات لهذا المشغل في كتالوج الخادم حالياً.',icon:Icons.cloud_off_outlined)
    else for(final s in services) _ServerServiceCard(service:s,color:color,phone:phone),
  ])));
  }
}

