class _ServiceDialog extends StatefulWidget { const _ServiceDialog({required this.service,required this.color,required this.phone,this.item}); final Map<String,dynamic> service; final Map<String,dynamic>? item; final Color color; final TextEditingController phone; @override State<_ServiceDialog> createState()=>_ServiceDialogState(); }
class _ServiceDialogState extends State<_ServiceDialog>{final ctrls=<String,TextEditingController>{};bool busy=false;
  @override void initState(){super.initState();final f=widget.service['fields'];if(f is List)for(final raw in f.whereType<Map>()){final key='${raw['key']??''}';ctrls[key]=TextEditingController(text:(key=='mobile'||key=='phone')?widget.phone.text:'${raw['default']??''}');}if(widget.item!=null&&ctrls.containsKey('amount')&&ctrls['amount']!.text.isEmpty)ctrls['amount']!.text='${widget.item!['price']??''}';}
  @override void dispose(){for(final c in ctrls.values)c.dispose();super.dispose();}
  Future<void> run()async{final payload=<String,dynamic>{};for(final e in ctrls.entries)if(e.value.text.trim().isNotEmpty)payload[e.key]=e.value.text.trim();setState(()=>busy=true);try{final id=int.tryParse('${widget.service['id']}');if(id==null)throw Exception('الخدمة غير صالحة');final r=await context.read<AppController>().requestService(serviceId:id,payload:payload,itemId:widget.item==null?null:int.tryParse('${widget.item!['id']}'),itemType:widget.item?['type']?.toString());if(mounted){Navigator.pop(context);await showDialog(context:context,builder:(_)=>AlertDialog(title:Text(r['status']=='failed'?'فشل الطلب':'نتيجة العملية',textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w900)),content:Text('${r['result']??r['error_message']??'تم إرسال الطلب'}\nالمرجع: ${r['id']??'-'}',textAlign:TextAlign.center,style:const TextStyle(fontSize:11,height:1.5)),actions:[FilledButton(onPressed:()=>Navigator.pop(context),child:const Text('تم'))]));}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}}
  @override Widget build(BuildContext context){final fields=widget.service['fields'] is List?(widget.service['fields'] as List).whereType<Map>().toList():<Map<String,dynamic>>[];return AlertDialog(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(21)),title:Text('${widget.service['name']??'تنفيذ الخدمة'}',textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w900)),content:SizedBox(width:430,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[if(widget.item!=null)Container(width:double.infinity,padding:const EdgeInsets.all(9),margin:const EdgeInsets.only(bottom:8),decoration:BoxDecoration(color:widget.color.withOpacity(.08),borderRadius:BorderRadius.circular(12)),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('${widget.item!['name']??'العنصر'}',style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900)),Text(money(widget.item!['price']),style:TextStyle(color:widget.color,fontWeight:FontWeight.w900))])),for(final f in fields)Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:ctrls['${f['key']??''}'],obscureText:f['secret']==true,decoration:InputDecoration(labelText:'${f['label']??f['key']}',hintText:f['choices'] is List&&((f['choices'] as List).isNotEmpty)?'اختيارات: ${(f['choices'] as List).join('، ')}':null,isDense:true)))])),actions:[TextButton(onPressed:busy?null:()=>Navigator.pop(context),child:const Text('إلغاء')),FilledButton(onPressed:busy?null:run,style:FilledButton.styleFrom(backgroundColor:widget.color),child:Text(busy?'...':'تنفيذ'))]);}
}

