class _SupportScreenState extends State<SupportScreen>{final message=TextEditingController();Map<String,dynamic>? data;bool busy=false;@override void initState(){super.initState();_load();}@override void dispose(){message.dispose();super.dispose();}Future<void>_load()async{try{data=await context.read<AppController>().api.support();if(mounted)setState((){});}catch(_){}}Future<void>_send()async{if(message.text.trim().isEmpty)return;setState(()=>busy=true);try{data=await context.read<AppController>().api.sendSupportMessage(message.text.trim());message.clear();if(mounted)setState((){});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext context){final conv=data?['conversation'];final msgs=conv is Map&&conv['messages'] is List?conv['messages'] as List:const[];return Scaffold(appBar:AppBar(title:const Text('التواصل مع الإدارة')),body:Column(children:[Expanded(child:msgs.isEmpty?const Center(child:Text('لا توجد رسائل بعد.',style:TextStyle(color:AppColors.muted))):ListView.builder(padding:const EdgeInsets.all(12),itemCount:msgs.length,itemBuilder:(_,i){final m=Map<String,dynamic>.from(msgs[i] as Map);final mine=m['sender_role']=='customer'||m['senderRole']=='customer';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:7),padding:const EdgeInsets.symmetric(horizontal:11,vertical:9),decoration:BoxDecoration(color:mine?AppColors.burgundy:Colors.white,borderRadius:BorderRadius.circular(14),border:Border.all(color:AppColors.border)),child:Text('${m['body']??''}',style:TextStyle(fontSize:10.5,color:mine?Colors.white:Colors.black87)));})),SafeArea(child:Container(padding:const EdgeInsets.all(9),decoration:const BoxDecoration(color:Colors.white),child:Row(children:[Expanded(child:TextField(controller:message,maxLines:3,decoration:const InputDecoration(hintText:'اكتب رسالتك...',isDense:true))),IconButton(onPressed:busy?null:_send,style:IconButton.styleFrom(backgroundColor:AppColors.burgundy,foregroundColor:Colors.white),icon:const Icon(Icons.send_rounded))])))]));}}

