class _OperationTile extends StatelessWidget { const _OperationTile({required this.operation}); final Map<String,dynamic> operation; @override Widget build(BuildContext context){final status='${operation['status']??''}';final c=['success','completed'].contains(status)?AppColors.emerald:['failed','rejected'].contains(status)?Colors.red:AppColors.amber;return PageCard(margin:const EdgeInsets.only(bottom:7),padding:const EdgeInsets.all(9),child:Row(children:[Icon(['success','completed'].contains(status)?Icons.check_circle_rounded:Icons.schedule_rounded,color:c,size:20),const SizedBox(width:8),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${operation['service']??'عملية خدمة'}',style:const TextStyle(fontSize:10.5,fontWeight:FontWeight.w900)),Text('${operation['created_at']??''}',style:const TextStyle(fontSize:8,color:Colors.black45))])),Text('${operation['amount']??''} ${operation['currency']??'YER'}',style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900,color:AppColors.burgundy))]));}}
class _StatementRow extends StatelessWidget { const _StatementRow({required this.row}); final Map<String,dynamic> row; @override Widget build(BuildContext context)=>PageCard(margin:const EdgeInsets.only(bottom:6),padding:const EdgeInsets.symmetric(horizontal:10,vertical:9),child:Row(children:[const Icon(Icons.swap_vert_rounded,color:AppColors.blue,size:18),const SizedBox(width:7),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${row['description']??row['service']??row['reference']??'قيد محاسبي'}',style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900)),Text('${row['date']??row['created_at']??''}',style:const TextStyle(fontSize:8,color:Colors.black45))])),Text('${row['amount']??row['value']??0} ${row['currency']??'YER'}',style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900))]));}
