class _ProductCard extends StatelessWidget { const _ProductCard({required this.product,required this.quantity,required this.onAdd,required this.onRemove,required this.onTap}); final Product product; final int quantity; final VoidCallback onAdd; final VoidCallback? onRemove; final VoidCallback onTap; @override Widget build(BuildContext context){final img=absoluteUrl(product.image);final price=product.salePrice??product.price;return InkWell(onTap:onTap,borderRadius:BorderRadius.circular(17),child:Container(clipBehavior:Clip.antiAlias,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(17),border:Border.all(color:AppColors.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Expanded(child:img.isEmpty?const Center(child:Icon(Icons.image_outlined,size:44,color:Colors.black26)):Image.network(img,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Center(child:Icon(Icons.image_not_supported_outlined,size:42,color:Colors.black26)))),Padding(padding:const EdgeInsets.fromLTRB(8,7,8,2),child:Text(product.name,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900))),Padding(padding:const EdgeInsets.symmetric(horizontal:8),child:Text(money(price,product.currency),style:const TextStyle(fontSize:12,fontWeight:FontWeight.w900,color:AppColors.burgundy))),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[IconButton(onPressed:onRemove,icon:const Icon(Icons.remove_circle_outline_rounded,size:18)),Text('$quantity',style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900)),IconButton(onPressed:product.stock>0?onAdd:null,icon:const Icon(Icons.add_circle_rounded,size:18,color:AppColors.emerald))])]));}}
